    INSERT INTO public.social_media_posts (day, title, description, user_id, status) VALUES
    (1, 'What Is Clinical Documentation Integrity?', 'Clinical Documentation Integrity (CDI) is the practice of systematically reviewing, clarifying, and optimizing a patient''s medical record so it accurately reflects their diagnoses, treatments, and clinical status—ensuring quality of care, regulatory compliance, and appropriate reimbursement.', auth.uid(), 'draft'),
    (2, 'What Is the Role of a Clinical Documentation Specialist?', 'A Clinical Documentation Specialist (CDS) is a nursing-educated professional who reviews patient charts in real time and retrospectively, identifies documentation gaps, and collaborates with providers to clarify clinical details—supporting accurate coding, risk mitigation, and revenue capture.', auth.uid(), 'draft'),
    (3, 'What Is a Medical Chart''s Anatomy?', 'The anatomy of a medical chart comprises admission notes, physician progress reports, diagnostic and imaging results, medication administration records, and discharge summaries—forming the comprehensive clinical narrative that underlies coding and quality measurement.', auth.uid(), 'draft'),
    (4, 'What Is the Structure of ICD-10-CM Codes?', 'ICD-10-CM codes are organized in a hierarchical, alphanumeric system of chapters, categories, and subcategories that translate clinical conditions into standardized data—enabling statistical reporting, DRG grouping, and epidemiologic analysis.', auth.uid(), 'draft'),
    (5, 'What Are CPT & HCPCS Procedure Codes?', 'CPT and HCPCS codes are standardized numeric and alphanumeric identifiers for medical procedures, services, and supplies—facilitating consistent billing, utilization monitoring, and payer communication.', auth.uid(), 'draft'),
    (6, 'What Is MS-DRG Grouping?', 'MS-DRG grouping assigns inpatient cases to Diagnosis-Related Groups based on principal and secondary diagnoses, procedures, age, and discharge status—determining prospective payment and aligning reimbursement with case complexity.', auth.uid(), 'draft'),
    (7, 'What Is Case Mix Index (CMI)?', 'Case Mix Index (CMI) measures the average relative weight of a hospital''s DRG portfolio, reflecting patient complexity and resource use—serving as a key benchmark for financial performance and operational strategy.', auth.uid(), 'draft'),
    (8, 'What Is Medical Necessity?', 'Medical necessity is the documentation of services that are reasonable and required for diagnosis and treatment of a patient''s condition—forming the foundation for payer coverage decisions and audit defense.', auth.uid(), 'draft'),
    (9, 'What Is a Principal vs. Secondary Diagnosis?', 'A principal diagnosis is the condition chiefly responsible for patient admission, while secondary diagnoses capture comorbidities and complications—both driving DRG assignment, clinical complexity, and revenue impact.', auth.uid(), 'draft'),
    (10, 'What Is Severity of Illness & Complexity of Care?', 'Severity of illness gauges physiologic decompensation or organ dysfunction, and complexity of care reflects treatment intensity—both must be documented to justify resource utilization and accurate DRG reimbursement.', auth.uid(), 'draft'),
    (11, 'What Are CCs & MCCs?', 'Complications or Comorbidities (CCs) and Major Complications or Comorbidities (MCCs) are secondary diagnoses that elevate DRG weight—ensuring capture of additional resource use and enhancing reimbursement accuracy.', auth.uid(), 'draft'),
    (12, 'What Is the CDI Query Process?', 'The CDI query process involves identifying ambiguous or missing documentation, drafting a compliant query to the provider, and recording their clarification—closing gaps to support precise coding and billing.', auth.uid(), 'draft'),
    (13, 'What Makes an Effective CDI Query?', 'An effective CDI query is clear, concise, and adheres to regulatory and coding guidelines, providing relevant clinical context without leading language—facilitating timely, unbiased provider responses.', auth.uid(), 'draft'),
    (14, 'What Does "Avoid Leading Queries" Mean?', 'Avoiding leading queries means framing neutral, open-ended questions that do not suggest a specific diagnosis or procedure—ensuring provider clarifications are driven solely by clinical judgment.', auth.uid(), 'draft'),
    (15, 'What Is Clinical vs. Coding Validation?', 'Clinical validation confirms that documentation accurately reflects the patient''s health status and care, while coding validation ensures that code assignments align with documentation, coding rules, and payer requirements.', auth.uid(), 'draft'),
    (16, 'What Is the CDI Workflow?', 'The CDI workflow spans admission review, concurrent and retrospective chart audits, provider queries, coding collaboration, and reporting—establishing a continuous process for documentation oversight and improvement.', auth.uid(), 'draft'),
    (17, 'What Are Key CDI Metrics?', 'Key CDI metrics include query rate, provider response rate, average response time, CMI change, and revenue impact—quantifying program effectiveness, operational efficiency, and financial return.', auth.uid(), 'draft'),
    (18, 'What Is CDI''s Role in Quality Measures?', 'CDI underpins quality measure accuracy by ensuring documentation captures all relevant diagnoses, treatments, and outcomes—supporting HEDIS, core measures, and value-based purchasing reporting.', auth.uid(), 'draft'),
    (19, 'What Are HCCs & Risk Adjustment?', 'Hierarchical Condition Categories (HCCs) are risk-adjustment codes used in value-based payment models to predict future costs—requiring comprehensive documentation of chronic and complex conditions to optimize reimbursement.', auth.uid(), 'draft'),
    (20, 'What Is EHR-Integrated CDI Technology?', 'EHR-integrated CDI technology embeds documentation-improvement tools, smart alerts, and interactive dashboards within the electronic health record—automating chart identification, query tracking, and performance monitoring.', auth.uid(), 'draft'),
    (21, 'What Is NLP''s Role in CDI?', 'Natural Language Processing (NLP) applies AI to unstructured clinical text, identifying potential documentation improvement opportunities and prioritizing high-impact charts—enabling scalable, proactive CDI.', auth.uid(), 'draft'),
    (22, 'What Is Data Analytics for CDI?', 'Data analytics for CDI leverages dashboards, trend analyses, and predictive models to pinpoint documentation patterns, target high-value cases, and monitor program performance for continuous optimization.', auth.uid(), 'draft'),
    (23, 'What Is Provider Engagement in CDI?', 'Provider engagement in CDI involves educating clinicians on documentation best practices, sharing performance insights, and fostering collaboration—driving sustained improvements in record accuracy and completeness.', auth.uid(), 'draft'),
    (24, 'What Is Audit & Compliance in CDI?', 'Audit and compliance in CDI prepare clinical records for internal and external reviews by aligning documentation with CMS, OIG, and payer regulations—mitigating audit risk and strengthening defense.', auth.uid(), 'draft'),
    (25, 'What Is Preparing for Internal vs. External Audits?', 'Preparing for internal vs. external audits includes conducting self-assessments, performing gap analyses, educating staff, and compiling supporting evidence—ensuring readiness for both organizational and third-party reviews.', auth.uid(), 'draft'),
    (26, 'What Is CDI''s Role in Appeals & Denials?', 'CDI supports appeals and denials management by leveraging accurate, detailed documentation and provider clarifications to build compelling medical necessity arguments—reducing denials and recapturing revenue.', auth.uid(), 'draft'),
    (27, 'What Is an Effective CDI Team Structure?', 'An effective CDI team structure combines CDI specialists, physician advisors, coding partners, and data analysts—facilitating cross-functional collaboration, workflow efficiency, and documentation excellence.', auth.uid(), 'draft'),
    (28, 'What Is Ongoing CDI Training?', 'Ongoing CDI training includes continuous education on coding updates, regulatory changes, query best practices, and emerging technologies—equipping CDSs with up-to-date knowledge and skills.', auth.uid(), 'draft'),
    (29, 'What Is CDI ROI Measurement?', 'CDI ROI measurement quantifies financial gains and clinical improvements by analyzing net revenue increase, CMI shifts, denial reductions, and cost savings against program investments.', auth.uid(), 'draft'),
    (30, 'What Are Future Trends in CDI?', 'Future trends in CDI encompass AI-driven automation, advanced risk-adjustment methodologies, real-time analytics, and integrated clinician feedback loops—proactively optimizing documentation quality and operational efficiency.', auth.uid(), 'draft');
